-- ----------------------------------------------------- 
-- Environment Variables
-- name: "Default"
-- ----------------------------------------------------- 

-- Default Settings in ml4w.conf

-- Pavucontrol floating
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    name = "pulseaudio-pavucontrol",
    match = {
        class = "(.*org.pulseaudio.pavucontrol.*)",
    },
    size = "{700, 600}",
    float = true,
    center = true,
    pin = true,
})

-- Waypaper
hl.window_rule({
    name = "waypaper",
    match = {
        class = "(.*waypaper.*)",
    },
    size = "{900, 700}",
    float = true,
    center = true,
    pin = true,
})

-- System Mission Center
hl.window_rule({
    name = "mission-center",
    match = {
        class = "(io.missioncenter.MissionCenter)",
    },
    size = "{900, 600}",
    float = true,
    center = true,
    pin = true,
})

hl.window_rule({
    name = "mission-center-prefs",
    match = {
        class = "(missioncenter)",
        title = "^(Preferences)$",
    },
    float = true,
    center = true,
    pin = true,
})

-- Gnome Calculator
hl.window_rule({
    name = "gnome-calc",
    match = {
        class = "(org.gnome.Calculator)",
    },
    size = "{700, 600}",
    float = true,
    center = true,
})

-- Emoji Picker
hl.window_rule({
    name = "emoji-picker",
    match = {
        class = "(it.mijorus.smile)",
    },
    move = "\"100%-w-40 90\"",
    float = true,
    pin = true,
})

-- Hyprland Share Picker
hl.window_rule({
    name = "hyprland-share-picker",
    match = {
        class = "(hyprland-share-picker)",
    },
    size = "{600, 400}",
    float = true,
    center = true,
    pin = true,
})

-- General floating
hl.window_rule({
    name = "dotfiles-floating",
    match = {
        class = "(dotfiles-floating)",
    },
    size = "{1000, 700}",
    float = true,
    center = true,
    pin = true,
})

-- XDG Desktop Portal
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")

-- QT
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")
hl.env("QT_QPA_PLATFORMTHEME", "qt5ct")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QT_AUTO_SCREEN_SCALE_FACTOR", "1")

-- GDK
hl.env("GDK_SCALE", "1")

-- Toolkit Backend
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("CLUTTER_BACKEND", "wayland")

-- Mozilla
hl.env("MOZ_ENABLE_WAYLAND", "1")

-- Set the cursor size for xcursor
hl.env("XCURSOR_SIZE", "24")

-- Disable appimage launcher by default
hl.env("APPIMAGELAUNCHER_DISABLE", "1")

-- Ozone
hl.env("OZONE_PLATFORM", "wayland")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "wayland")

-- Python
hl.env("PYTHONPATH", "/usr/lib/python3.12/site-packages:/usr/lib/python3.13/site-packages")
